//! Speed: one generated file of more than 5 MB, extracted and merged (untouched and fully translated), timed.
//! The same file is generated by `scratchpad/speed_locos.py` for the Localization OS filter. Run with
//! `cargo test -p bilingua-json5 --release --test speed -- --nocapture` to see the times.

use bilingua_json5::{Json5Filter, Limits};
use bilingua_model::*;
use std::time::Instant;

const ENTRIES: usize = 70_000;

fn generate() -> String {
    let mut s = String::from("// generated\n{\n");
    for i in 0..ENTRIES {
        s.push_str(&format!("  // note {i}\n  key{i}: 'Value number {i} with {{name}} and <b>bold</b> text, it{bs}'s fine.',\n", bs = '\x5c'));
    }
    s.push_str("}\n");
    s
}

#[test]
fn large_file_extract_and_merge_speed() {
    let src = generate();
    assert!(src.len() > 5_000_000, "{} bytes", src.len());
    let f = Json5Filter::with_limits(Limits { max_units: 1_000_000, ..Limits::default() });
    let o = ExtractOptions::new().with_source_lang("en").with_target_lang("de").with_granularity(Granularity::Paragraph);

    let t0 = Instant::now();
    let mut doc = f.extract(src.as_bytes(), &o).unwrap();
    let t_extract = t0.elapsed();
    assert_eq!(doc.units.len(), ENTRIES);

    let t1 = Instant::now();
    let same = f.merge(&doc).unwrap();
    let t_untouched = t1.elapsed();
    assert_eq!(same, src.as_bytes());

    for u in &mut doc.units {
        let mut t = vec![Inline::text("DE ")];
        t.extend(u.segments[0].source.iter().cloned());
        u.segments[0].target = t;
    }
    let t2 = Instant::now();
    let out = f.merge(&doc).unwrap();
    let t_translated = t2.elapsed();
    assert!(out.len() > src.len());
    println!(
        "SPEED bytes={} units={} extract={:?} merge_untouched={:?} merge_translated={:?} total={:?}",
        src.len(),
        ENTRIES,
        t_extract,
        t_untouched,
        t_translated,
        t_extract + t_translated
    );
    assert!((t_extract + t_translated).as_secs() < 60);
}
